package top.monitorglobal.tv;
import android.content.*;import android.os.*;import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.*;import org.json.*;
/** Optional, independent I/O. Never blocks forecast delivery or creates a notification. */
final class WeatherBriefingClient implements AutoCloseable {
 private final SharedPreferences cache;private final Handler main=new Handler(Looper.getMainLooper());private final Runnable changed;private final Set<String> busy=new HashSet<>();private final Map<String,Long> retry=new HashMap<>();private final Map<String,Integer> pending=new HashMap<>();private final Set<HttpURLConnection> connections=Collections.synchronizedSet(new HashSet<>());private ExecutorService worker;private boolean closed;private int generation;
 WeatherBriefingClient(Context c,Runnable callback){cache=c.getApplicationContext().getSharedPreferences("weather-ai",Context.MODE_PRIVATE);changed=callback;}
 static String text(Context c,String kind,WeatherForecast.Summary w,RainForecast.Summary r){long now=System.currentTimeMillis();WeatherBriefing value=WeatherBriefing.parse(c.getApplicationContext().getSharedPreferences("weather-ai",Context.MODE_PRIVATE).getString(kind,""),now);return value==null?"":value.forForecast(w,r,now);}
 void prefetch(String kind,WeatherForecast.Summary w,RainForecast.Summary r){
  if(closed||!(kind.equals("hourly")||kind.equals("rain"))||kind.equals("hourly")&&w==null||kind.equals("rain")&&(r==null||r.state.equals("dry")))return;
  if(!textFrom(kind,w,r).isEmpty()||busy.contains(kind)||System.currentTimeMillis()<retry.getOrDefault(kind,0L))return;
  busy.add(kind);final int token=generation;if(worker==null)worker=Executors.newFixedThreadPool(2);worker.execute(()->{String raw="";int pending=0;try{raw=read(kind);JSONObject d=new JSONObject(raw);if("pending".equals(d.optString("status")))pending=1;}catch(Exception ignored){}String result=raw;int again=pending;main.post(()->{if(closed||token!=generation)return;busy.remove(kind);WeatherBriefing value=WeatherBriefing.parse(result,System.currentTimeMillis());if(value!=null){cache.edit().putString(kind,result).apply();retry.remove(kind);pending.remove(kind);if(changed!=null)changed.run();}else{int attempts=pending.getOrDefault(kind,0)+1;pending.put(kind,attempts);long delay=again==1&&attempts<=4?2000:300000;retry.put(kind,System.currentTimeMillis()+delay);if(again==1&&attempts<=4)main.postDelayed(()->prefetch(kind,w,r),delay);}});});
 }
 private String textFrom(String kind,WeatherForecast.Summary w,RainForecast.Summary r){WeatherBriefing b=WeatherBriefing.parse(cache.getString(kind,""),System.currentTimeMillis());return b==null?"":b.forForecast(w,r,System.currentTimeMillis());}
 private String read(String kind)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL("https://black-sky-9ba0.terrestre.workers.dev/weather-briefing?kind="+kind).openConnection();connections.add(c);c.setConnectTimeout(4000);c.setReadTimeout(6000);c.setInstanceFollowRedirects(false);c.setRequestProperty("Accept","application/json");c.setRequestProperty("User-Agent","MonitorGlobalWeatherBriefing");try{if(c.getResponseCode()!=200)throw new IOException("Unavailable");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream in=c.getInputStream()){byte[] b=new byte[1024];int n;while((n=in.read(b))!=-1){if(bytes.size()+n>6000)throw new IOException("Too large");bytes.write(b,0,n);}}return bytes.toString("UTF-8");}finally{c.disconnect();connections.remove(c);}}
 void pause(){generation++;main.removeCallbacksAndMessages(null);busy.clear();synchronized(connections){for(HttpURLConnection c:connections)c.disconnect();connections.clear();}}
 public void close(){closed=true;pause();if(worker!=null)worker.shutdownNow();}
}
